  let split = vec2f(px.x, 0.0) * rim * uniforms.intensity;
  let backdrop_r = sample_backdrop(uv + bend + split);
  let backdrop_g = sample_backdrop(uv + bend);
  let backdrop_b = sample_backdrop(uv + bend - split);
